const DAILY_20261001=[{"id":"aussie-meat-pie","n":"Aussie Meat Pie (Australian Beef and Gravy Pie)","c":"Australia","f":"🇦🇺","m":60,"x":["puff pastry","ground beef","onion","beef broth","flour","tomato"],"s":["Cook the ground beef and onion until browned and no pink remains.","Stir in flour, tomato, and broth, then simmer until the filling is thick.","Line a small pie dish with pastry, add the cooled filling, and cover with more pastry.","Seal, vent, and bake until the crust is deeply golden and the filling is piping hot."],"co":"#b87338","source":"https://www.australia.com/en-in/things-to-do/food-and-drinks/australias-bucket-list-food-experiences.html","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"lamington","n":"Lamington (Australian Chocolate-Coconut Sponge Cake)","c":"Australia","f":"🇦🇺","m":55,"x":["flour","egg","sugar","butter","milk","cocoa","coconut"],"s":["Beat egg and sugar until pale, then fold in flour, melted butter, and milk.","Bake in a shallow tin until the sponge springs back, then cool completely.","Cut into cubes and coat each piece in a thin cocoa icing.","Roll in coconut and let the coating set before serving."],"co":"#7d4d39","source":"https://www.australia.com/en-my/things-to-do/food-and-drinks/typical-aussie-foods-to-try.html","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"stamppot","n":"Stamppot (Dutch Mashed Potato and Kale)","c":"Netherlands","f":"🇳🇱","m":40,"x":["potato","kale","butter","milk","sausage","onion"],"s":["Boil the potato and kale together until both are tender.","Drain well, then mash with butter and warm milk.","Cook the sausage until heated through and brown the onion separately.","Season the mash and serve it with sausage and onion on top."],"co":"#d07b34","source":"https://www.holland.com/global/tourism/holland-stories/dutch-food-and-cuisine.htm","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"erwtensoep","n":"Erwtensoep (Dutch Split-Pea Soup)","c":"Netherlands","f":"🇳🇱","m":95,"x":["split peas","pork","sausage","carrot","leek","celery"],"s":["Rinse the split peas and simmer them with pork in water until they begin to break down.","Add carrot, leek, and celery and cook until very soft.","Remove and slice the pork, then return it with sliced sausage.","Simmer until the soup is thick enough to coat a spoon and season to taste."],"co":"#5e7d45","source":"https://www.holland.com/global/tourism/get-inspired/current/sustainable-holiday/deliciously-sustainable-dutch-food","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"cepelinai","n":"Cepelinai (Lithuanian Meat-Filled Potato Dumplings)","c":"Lithuania","f":"🇱🇹","m":80,"x":["potato","ground beef","onion","flour","sour cream","bacon"],"s":["Grate part of the potato raw and squeeze it dry; mash the remaining cooked potato.","Combine both potatoes with flour to make a moldable mixture.","Wrap seasoned beef and onion filling inside oval potato dumplings.","Simmer gently until cooked through, then serve with sour cream and crisp bacon."],"co":"#c5a242","source":"https://lithuania.travel/en/what-to-do/food-and-drink/lithuanian-products/cepelinai","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"saltibarsciai","n":"Šaltibarščiai (Lithuanian Cold Beet-Kefir Soup)","c":"Lithuania","f":"🇱🇹","m":25,"x":["beetroot","kefir","cucumber","egg","dill","potato"],"s":["Grate the cooked beetroot and finely dice the cucumber.","Stir them into cold kefir with dill and a pinch of salt.","Chill briefly while boiling the egg and potato separately.","Top the pink soup with egg and serve the warm potato alongside."],"co":"#d94f87","source":"https://lithuania.travel/en/what-to-do/food-and-drink/lithuanian-products","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"irish-stew","n":"Irish Stew (Irish Lamb and Root-Vegetable Stew)","c":"Ireland","f":"🇮🇪","m":105,"x":["lamb","potato","onion","carrot","beef broth","parsley"],"s":["Brown the lamb lightly in a heavy pot.","Layer in onion, carrot, and potato, then pour over the broth.","Cover and simmer gently until the lamb and vegetables are tender.","Skim excess fat, adjust seasoning, and finish with parsley."],"co":"#477a50","source":"https://www.visitdublin.com/guides/irish-food","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"colcannon","n":"Colcannon (Irish Kale Mashed Potatoes)","c":"Ireland","f":"🇮🇪","m":35,"x":["potato","kale","butter","milk","onion","bacon"],"s":["Boil the potato until tender and drain it well.","Cook the kale and onion until soft, then finely chop them.","Mash the potato with warm milk and butter.","Fold in the greens, top with crisp bacon, and serve hot."],"co":"#6d8746","source":"https://www.ireland.com/en-ca/magazine/food-and-drink/st-patricks-day-recipes/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"sarmale","n":"Sarmale (Romanian Pork and Rice Cabbage Rolls)","c":"Romania","f":"🇷🇴","m":130,"x":["cabbage","pork","rice","onion","tomato","sour cream"],"s":["Soften the cabbage leaves and trim the thick ribs.","Mix pork, rinsed rice, onion, tomato, salt, and pepper.","Wrap small portions in cabbage leaves and arrange them tightly in a pot.","Add water and tomato, simmer gently until cooked through, and serve with sour cream."],"co":"#b34f44","source":"https://www.romania.travel/ro/category/gusta","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"mamaliga","n":"Mămăligă (Romanian Cornmeal Porridge)","c":"Romania","f":"🇷🇴","m":25,"x":["cornmeal","water","salt","butter","cheese","sour cream"],"s":["Bring salted water to a steady simmer.","Rain in the cornmeal slowly while whisking to prevent lumps.","Cook over low heat, stirring, until the mixture pulls from the pan.","Finish with butter and serve with cheese and sour cream."],"co":"#d6b13f","source":"https://www.romania.travel/en/category/taste","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."}];
window.EXTRA_RECIPES=(window.EXTRA_RECIPES||[]).concat(DAILY_20261001);
